import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';
import { HydratedDocument } from 'mongoose';
import {
  MAX_DURATION_MINUTES,
  MAX_RELEASE_YEAR,
  MAX_TITLE_LENGTH,
  MIN_RELEASE_YEAR,
} from '../../common/limits';
import { integerValidator } from '../../common/schema-validators';

/**
 * Collection `films`. _id is generated by MongoDB.
 * The rules repeat the DTO checks, so a document written past the API
 * (e.g. by the seed script) is validated by the schema as well.
 */
@Schema({ collection: 'films', versionKey: false })
export class Film {
  @Prop({ required: true, trim: true, maxlength: MAX_TITLE_LENGTH })
  title: string;

  @Prop({
    required: true,
    min: 1,
    max: MAX_DURATION_MINUTES,
    validate: integerValidator,
  })
  durationMinutes: number;

  @Prop({
    required: true,
    min: MIN_RELEASE_YEAR,
    max: MAX_RELEASE_YEAR,
    validate: integerValidator,
  })
  releaseYear: number;
}

export type FilmDocument = HydratedDocument<Film>;
export const FilmSchema = SchemaFactory.createForClass(Film);
